import re
from collections import Counter
from math import comb

def norm(s):
    return re.sub(r"[^a-z0-9 ]", "", s.lower()).strip()

def exact_match(pred, gold):
    return norm(pred) == norm(gold)

def token_f1(pred, gold):
    p, g = norm(pred).split(), norm(gold).split()
    common = sum((Counter(p) & Counter(g)).values())
    if common == 0:
        return 0.0
    prec, rec = common / len(p), common / len(g)
    return 2 * prec * rec / (prec + rec)

print(exact_match("The Eiffel Tower!", "the eiffel tower"))
print(round(token_f1("the tower in Paris", "the Eiffel tower"), 3))

# pass@k (Chen et al. 2021): xác suất ÍT NHẤT một trong k mẫu đúng, ước lượng không chệch từ n mẫu, c đúng
def pass_at_k(n, c, k):
    if n - c < k:
        return 1.0
    return 1.0 - comb(n - c, k) / comb(n, k)

print([round(pass_at_k(10, 3, k), 3) for k in (1, 5, 10)])

